var e={machineDoctor:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Ein Nur-Lese-Scan über alles Prüfbare — Pin-Konflikte, Treiberwerte, Config-Drift, Projekt-Lint, Firmware-Sync, Hardware-Änderungen, Installations-Gesundheit — benotet A-F. Jeder Befund verlinkt zum Widget, das ihn behebt.`}},scanning:{t:0,b:{t:2,i:[{t:3}],s:`Scanne…`}},rescan:{t:0,b:{t:2,i:[{t:3}],s:`Erneut scannen`}},scoreLine:{t:0,b:{t:2,i:[{t:3,v:`Punktzahl `},{t:4,k:`score`},{t:3,v:` / 100`}]}},counts:{t:0,b:{t:2,i:[{t:4,k:`errors`},{t:3,v:` Fehler · `},{t:4,k:`warnings`},{t:3,v:` Warnung(en)`}]}},scoreHint:{t:0,b:{t:2,i:[{t:3}],s:`Eine gewichtete Mischung der unten stehenden Säulen. Gesundheitsprüfungen (Konfig-Integrität, Firmware-Sync, Dienste) bewerten, was wir messen konnten — die Konfig-Integrität verliert 25 Punkte pro Fehler und 8 pro Warnung. Einrichtungsschritte, die Sie noch nicht durchgeführt haben (Input Shaping, Max. Fluss, Motortreiber), zählen als null, bis sie erledigt sind, sodass ihre Fertigstellung die Punktzahl anhebt. Signale, die sich gerade nicht auslesen lassen, zählen nicht gegen Sie.`}},allClear:{t:0,b:{t:2,i:[{t:3}],s:`Alles in Ordnung.`}},notChecked:{t:0,b:{t:2,i:[{t:3}],s:`Konnte nicht geprüft werden (Drucker nicht erreichbar oder keine Basislinie).`}},assessment:{healthy:{t:0,b:{t:2,i:[{t:3}],s:`Gesund — alles, was die App prüfen kann, sieht gut aus und die Einrichtung ist abgeschlossen.`}},attention:{t:0,b:{t:2,i:[{t:3,v:`Größtenteils gesund, aber `},{t:4,k:`pillar`},{t:3,v:` braucht Aufmerksamkeit.`}]}},critical:{t:0,b:{t:2,i:[{t:4,k:`pillar`},{t:3,v:` hat ein Problem, das behoben werden sollte.`}]}},setup_incomplete:{t:0,b:{t:2,i:[{t:3,v:`Nichts kaputt, aber die Einrichtung ist noch nicht fertig — `},{t:4,k:`pillars`},{t:3,v:` noch durchzuführen.`}]}},clean_but_findings:{t:0,b:{t:2,i:[{t:3,v:`Nichts kaputt, aber es gibt `},{t:4,k:`warnings`},{t:3,v:` Warnung(en) zu beheben.`}]}}},pillars:{title:{t:0,b:{t:2,i:[{t:3}],s:`Gesundheits-Aufschlüsselung`}},notMeasured:{t:0,b:{t:2,i:[{t:3}],s:`nicht gemessen`}},notDone:{t:0,b:{t:2,i:[{t:3}],s:`noch nicht erledigt`}}},pillar:{config:{t:0,b:{t:2,i:[{t:3}],s:`Konfig-Integrität`}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Firmware-Sync`}},services:{t:0,b:{t:2,i:[{t:3}],s:`Dienste`}},tuning:{t:0,b:{t:2,i:[{t:3}],s:`Input Shaping`}},flow:{t:0,b:{t:2,i:[{t:3}],s:`Max. Fluss`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Motortreiber`}}},services:{title:{t:0,b:{t:2,i:[{t:3}],s:`Dienste`}},active:{t:0,b:{t:2,i:[{t:3}],s:`aktiv`}},inactive:{t:0,b:{t:2,i:[{t:3}],s:`gestoppt`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Keine Dienste.`}}},stats:{title:{t:0,b:{t:2,i:[{t:3}],s:`Auf einen Blick`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Max. Fluss`}},tuningAxis:{t:0,b:{t:2,i:[{t:3,v:`Shaper `},{t:4,k:`axis`}]}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Firmware`}},outOfSync:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` nicht synchron`}]}},allSynced:{t:0,b:{t:2,i:[{t:3}],s:`alle synchron`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Noch keine Messungen.`}}},category:{pins:{t:0,b:{t:2,i:[{t:3}],s:`Pin-Verdrahtung`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Treiberwerte`}},drift:{t:0,b:{t:2,i:[{t:3}],s:`Config-Drift`}},project:{t:0,b:{t:2,i:[{t:3}],s:`Config-Projekt`}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Firmware-Sync`}},hardware:{t:0,b:{t:2,i:[{t:3}],s:`Hardware-Änderungen`}},install:{t:0,b:{t:2,i:[{t:3}],s:`Installation`}}},status:{ok:{t:0,b:{t:2,i:[{t:3}],s:`OK`}},warn:{t:0,b:{t:2,i:[{t:3}],s:`Warnungen`}},fail:{t:0,b:{t:2,i:[{t:3}],s:`Probleme`}},unknown:{t:0,b:{t:2,i:[{t:3}],s:`Nicht geprüft`}},todo:{t:0,b:{t:2,i:[{t:3}],s:`Nicht erledigt`}}},link:{config_section:{t:0,b:{t:2,i:[{t:3}],s:`Konfig-Editor`}},config_file:{t:0,b:{t:2,i:[{t:3}],s:`Konfig-Editor`}},stepper:{t:0,b:{t:2,i:[{t:3}],s:`Motortreiber`}},topology_node:{t:0,b:{t:2,i:[{t:3}],s:`Board-Topologie`}},widget:{t:0,b:{t:2,i:[{t:3}],s:`Öffnen`}}},finding:{pins:{double_assign:{t:0,b:{t:2,i:[{t:3,v:`Pin `},{t:4,k:`pin`},{t:3,v:` auf `},{t:4,k:`mcu`},{t:3,v:` ist in mehreren Abschnitten belegt.`}]}},caveat:{t:0,b:{t:2,i:[{t:3,v:`Pin `},{t:4,k:`pin`},{t:3,v:` auf `},{t:4,k:`mcu`},{t:3,v:` trägt einen Elektronik-Hinweis.`}]}}},drivers:{over_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A übersteigt die ~`},{t:4,k:`cap`},{t:3,v:`-A-Treibergrenze.`}]}},near_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A liegt innerhalb 10% der ~`},{t:4,k:`cap`},{t:3,v:`-A-Grenze.`}]}},over_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A übersteigt den Nennstrom des `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},near_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A liegt innerhalb 10% des Nennstroms des `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},odd_microsteps:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: microsteps `},{t:4,k:`microsteps`},{t:3,v:` ist keine Zweierpotenz.`}]}}},drift:{pending:{t:0,b:{t:2,i:[{t:3}],s:`Klipper hat ungespeicherte SAVE_CONFIG-Änderungen.`}},param:{t:0,b:{t:2,i:[{t:3,v:`[`},{t:4,k:`section`},{t:3,v:`] `},{t:4,k:`key`},{t:3,v:`: Datei `},{t:4,k:`disk`},{t:3,v:` ≠ live `},{t:4,k:`live`},{t:3,v:`.`}]}},klipper_warning:{t:0,b:{t:2,i:[{t:4,k:`text`}]}}},project:{broken_include:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:`: Include "`},{t:4,k:`message`},{t:3,v:`" zeigt auf keine Datei.`}]}},orphan_driver:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:`: Treiberabschnitt "`},{t:4,k:`message`},{t:3,v:`" ohne passenden Stepper.`}]}}},firmware:{out_of_sync:{t:0,b:{t:2,i:[{t:4,k:`mcu`},{t:3,v:`: Firmware `},{t:4,k:`mcu_version`},{t:3,v:` weicht vom Host `},{t:4,k:`host_version`},{t:3,v:` ab.`}]}}},hardware:{changed:{t:0,b:{t:2,i:[{t:4,k:`mcu`},{t:3,v:`: Hardware geändert (`},{t:4,k:`kind`},{t:3,v:`).`}]}},no_baseline:{t:0,b:{t:2,i:[{t:3}],s:`Noch keine Hardware-Basislinie — in der Board-Topologie einen Snapshot speichern.`}}},install:{check_failed:{t:0,b:{t:2,i:[{t:3,v:`Installationsprüfung fehlgeschlagen: `},{t:4,k:`name`},{t:3,v:` — `},{t:4,k:`detail`},{t:3,v:`.`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Hilfe`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Über Machine Doctor`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Schließen`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`So liest du es`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Drücke „Erneut scannen“ für einen schreibgeschützten Rundum-Check des Druckers.`}},{t:0,b:{t:2,i:[{t:3}],s:`Lies die A–F-Note und die Säulen-Balken, um die Schwachstellen zu sehen.`}},{t:0,b:{t:2,i:[{t:3}],s:`Öffne den Link eines Befunds, um direkt zum Widget zu springen, das ihn behebt.`}}],topics:{scan:{title:{t:0,b:{t:2,i:[{t:3}],s:`Was der Scan prüft`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Ein schreibgeschützter Durchlauf über alles, was die App prüfen kann — Pin-Konflikte, Treiberwerte, Konfig-Abweichung zwischen gespeichert und live, Projekt-Lint, Firmware-Sync, Hardware-Änderungen gegenüber der Baseline und Installations-Gesundheit. Es wird nichts auf dem Drucker ausgeführt.`}}},grade:{title:{t:0,b:{t:2,i:[{t:3}],s:`Die A–F-Note`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Die Punktzahl vereint zwei Dinge. Gesundheitsprüfungen (Konfig-Integrität, Firmware-Sync, Dienste) bewerten, was wir messen konnten. Einrichtungsschritte — Input Shaping, Max. Fluss und die Abstimmung der Motortreiber — zählen als null, bis Sie sie durchführen, sodass ein nicht abgestimmter Drucker niedrig abschneidet, selbst wenn nichts kaputt ist, und jeder erledigte Schritt den Wert anhebt. Die Buchstabennote folgt direkt aus dieser Punktzahl, und ein Signal, das sich gerade nicht auslesen lässt (Moonraker oder der Host offline), fällt einfach heraus, statt gegen Sie zu zählen.`}}},fixes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sprung-zur-Lösung-Links`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Jeder Befund hat eine Schaltfläche, die direkt in das Widget verlinkt, das ihn behebt (Config-Editor, Motortreiber, die Maschinen-Karte…) — von Problem zu Lösung mit einem Klick.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Hier verwendete Begriffe`}}}},glossary:{grade:{term:{t:0,b:{t:2,i:[{t:3}],s:`Note (A–F)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Ein einzelner Buchstabe, der die Druckergesundheit zusammenfasst, abgeleitet aus den Säulen-Scores; A ist gesund, F braucht Aufmerksamkeit.`}}},pillar:{term:{t:0,b:{t:2,i:[{t:3}],s:`Säule`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Eine eigenständig bewertete Gesundheitskategorie — z. B. Konfig-Integrität, Firmware-Sync, Dienste, Input Shaping, Max-Flow.`}}},finding:{term:{t:0,b:{t:2,i:[{t:3}],s:`Befund`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Ein konkretes vom Scan erkanntes Problem, mit Schweregrad und einem Link zum Widget, das es behebt.`}}}}},listSep:{t:0,b:{t:2,i:[{t:3}],s:`, `}},setup:{line:{t:0,b:{t:2,i:[{t:3,v:`Vollständigkeit der Einrichtung: `},{t:4,k:`done`},{t:3,v:` / `},{t:4,k:`total`},{t:3,v:` Schritte erledigt`}]}}},readiness:{title:{t:0,b:{t:2,i:[{t:3}],s:`Einrichtungsbereitschaft`}},banner:{t:0,b:{t:2,i:[{t:3}],s:`Die Einrichtung ist noch nicht abgeschlossen — die nicht durchgeführten Schritte zählen als null und halten die Punktzahl zurück. Führen Sie sie durch, um sie anzuheben.`}},runIt:{t:0,b:{t:2,i:[{t:3}],s:`Durchführen`}}}}};export{e as default};